#!/usr/bin/env node
/**
 * Scaffolds a complete, isolated tool slice under `app/tools/<slug>/`.
 * See docs/TOOL_CONTRACT.md and scripts/verify-tools.mjs.
 *
 *   npm run new:tool -- fee-stats "Fee Stats"
 *
 * The generated slice compiles, renders and passes its own tests immediately;
 * the work is replacing the placeholder logic with the real tool. Nothing
 * outside app/tools/<slug>/ and tests/tools/<slug>/ is ever touched — the
 * homepage list is regenerated by scripts/generate-tools.mjs.
 */

import { mkdir, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

const [slug, titleArg] = process.argv.slice(2);

if (!slug || !/^[a-z][a-z0-9-]*$/.test(slug)) {
  console.error('Usage: npm run new:tool -- <kebab-slug> "<Title>"');
  process.exit(1);
}

const pascal = slug
  .split("-")
  .map((part) => part[0].toUpperCase() + part.slice(1))
  .join("");
const camel = pascal[0].toLowerCase() + pascal.slice(1);
const title = titleArg || slug.replace(/-/g, " ");

const toolDir = path.join(root, "app", "tools", slug);
const testDir = path.join(root, "tests", "tools", slug);

if (existsSync(toolDir)) {
  console.error(`app/tools/${slug} already exists`);
  process.exit(1);
}

const files = {
  "manifest.ts": `import { Sparkles } from "lucide-react";
import type { ToolManifest } from "@/lib/tool-manifest";

export const manifest: ToolManifest = {
  slug: "${slug}",
  title: "${title}",
  description: "TODO: one sentence describing what this tool does.",
  character: "TODO: one in-world character line.",
  href: "/tools/${slug}",
  status: "MVP",
  icon: Sparkles
};
`,

  "types.ts": `export interface ${pascal}Input {
  value: string;
}

export interface ${pascal}Result {
  value: string;
}

export type ${pascal}ErrorCode = "invalid_input" | "request_failed";

export interface ${pascal}Error {
  code: ${pascal}ErrorCode;
  message: string;
}
`,

  "schema.ts": `import type { ${pascal}Input, ${pascal}Error } from "@/app/tools/${slug}/types";

export function validate${pascal}Input(raw: string): { ok: true; input: ${pascal}Input } | { ok: false; error: ${pascal}Error } {
  const value = raw.trim();
  if (!value) {
    return { ok: false, error: { code: "invalid_input", message: "Enter a value first." } };
  }
  return { ok: true, input: { value } };
}
`,

  "copy.ts": `export const copy = {
  title: "${title}",
  idle: "TODO: idle-state copy.",
  loading: "TODO: loading-state copy.",
  empty: "TODO: empty-state copy.",
  errors: {
    invalid_input: "That value does not look right yet.",
    request_failed: "The request failed. Try again."
  }
};
`,

  [`lib/${camel}.ts`]: `import type { ${pascal}Input, ${pascal}Result } from "@/app/tools/${slug}/types";

export async function run${pascal}(input: ${pascal}Input): Promise<${pascal}Result> {
  // TODO: replace with the real Horizon/RPC-backed lookup.
  return { value: input.value };
}
`,

  [`lib/${camel}.errors.ts`]: `import type { ${pascal}Error } from "@/app/tools/${slug}/types";

export function toToolError(error: unknown): ${pascal}Error {
  if (error instanceof Error) {
    return { code: "request_failed", message: error.message };
  }
  return { code: "request_failed", message: "Unexpected error." };
}
`,

  "lib/format.ts": `export function formatResultValue(value: string): string {
  return value.trim();
}
`,

  [`hooks/use${pascal}.ts`]: `"use client";

import { useState } from "react";
import { validate${pascal}Input } from "@/app/tools/${slug}/schema";
import { run${pascal} } from "@/app/tools/${slug}/lib/${camel}";
import { toToolError } from "@/app/tools/${slug}/lib/${camel}.errors";
import type { ${pascal}Error, ${pascal}Result } from "@/app/tools/${slug}/types";

type State =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "success"; result: ${pascal}Result }
  | { status: "error"; error: ${pascal}Error };

export function use${pascal}() {
  const [state, setState] = useState<State>({ status: "idle" });

  async function submit(raw: string) {
    const parsed = validate${pascal}Input(raw);
    if (!parsed.ok) {
      setState({ status: "error", error: parsed.error });
      return;
    }
    setState({ status: "loading" });
    try {
      const result = await run${pascal}(parsed.input);
      setState({ status: "success", result });
    } catch (error) {
      setState({ status: "error", error: toToolError(error) });
    }
  }

  return { state, submit };
}
`,

  [`components/${pascal}Panel.tsx`]: `"use client";

import { CharacterPanel } from "@/components/ui/CharacterPanel";
import { Card } from "@/components/ui/Card";
import { use${pascal} } from "@/app/tools/${slug}/hooks/use${pascal}";
import { copy } from "@/app/tools/${slug}/copy";
import { ${pascal}Form } from "@/app/tools/${slug}/components/${pascal}Form";
import { ${pascal}Result } from "@/app/tools/${slug}/components/${pascal}Result";
import { ${pascal}EmptyState } from "@/app/tools/${slug}/components/${pascal}EmptyState";
import { StatusMessage } from "@/components/ui/StatusMessage";

export function ${pascal}Panel() {
  const { state, submit } = use${pascal}();

  return (
    <div className="mx-auto max-w-3xl space-y-6">
      <CharacterPanel tone="star" eyebrow="New helper" title={copy.title} description={copy.idle} />
      <Card className="space-y-5">
        <${pascal}Form onSubmit={submit} loading={state.status === "loading"} />
        {state.status === "idle" ? <${pascal}EmptyState /> : null}
        {state.status === "error" ? (
          <StatusMessage type="error" title="Something needs a fix" description={copy.errors[state.error.code]} />
        ) : null}
        {state.status === "success" ? <${pascal}Result result={state.result} /> : null}
      </Card>
    </div>
  );
}
`,

  [`components/${pascal}Form.tsx`]: `"use client";

import { useState } from "react";
import { Button } from "@/components/ui/Button";

interface Props {
  onSubmit: (value: string) => void;
  loading: boolean;
}

export function ${pascal}Form({ onSubmit, loading }: Props) {
  const [value, setValue] = useState("");

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        onSubmit(value);
      }}
      className="space-y-4"
    >
      <input
        value={value}
        onChange={(event) => setValue(event.target.value)}
        className="w-full rounded-md border border-[#cfe0ea] bg-white/80 px-3 py-2 text-sm"
        placeholder="TODO: describe the expected input"
      />
      <Button type="submit" disabled={loading}>
        {loading ? "Working..." : "Submit"}
      </Button>
    </form>
  );
}
`,

  [`components/${pascal}Result.tsx`]: `import type { ${pascal}Result as Result } from "@/app/tools/${slug}/types";
import { formatResultValue } from "@/app/tools/${slug}/lib/format";

export function ${pascal}Result({ result }: { result: Result }) {
  return <p className="text-sm text-[#172033]">{formatResultValue(result.value)}</p>;
}
`,

  [`components/${pascal}EmptyState.tsx`]: `export function ${pascal}EmptyState() {
  return <p className="text-sm text-[#68758a]">TODO: pre-interaction guidance.</p>;
}
`,

  "page.tsx": `export { ${pascal}Panel as default } from "@/app/tools/${slug}/components/${pascal}Panel";
`,

  "README.md": `# ${title}

TODO: describe behavior, data boundaries and design decisions for this tool.
`
};

const testFiles = {
  [`${camel}.test.ts`]: `import { describe, expect, it } from "vitest";
import { run${pascal} } from "@/app/tools/${slug}/lib/${camel}";

describe("run${pascal}", () => {
  it("returns a result for valid input", async () => {
    const result = await run${pascal}({ value: "example" });
    expect(result.value).toBe("example");
  });
});
`,

  "schema.test.ts": `import { describe, expect, it } from "vitest";
import { validate${pascal}Input } from "@/app/tools/${slug}/schema";

describe("validate${pascal}Input", () => {
  it("rejects empty input", () => {
    const result = validate${pascal}Input("  ");
    expect(result.ok).toBe(false);
  });

  it("accepts a trimmed value", () => {
    const result = validate${pascal}Input("  example  ");
    expect(result.ok).toBe(true);
  });
});
`,

  "format.test.ts": `import { describe, expect, it } from "vitest";
import { formatResultValue } from "@/app/tools/${slug}/lib/format";

describe("formatResultValue", () => {
  it("trims whitespace", () => {
    expect(formatResultValue("  example  ")).toBe("example");
  });
});
`
};

async function main() {
  for (const [file, content] of Object.entries(files)) {
    const filePath = path.join(toolDir, file);
    await mkdir(path.dirname(filePath), { recursive: true });
    await writeFile(filePath, content, "utf8");
  }

  for (const [file, content] of Object.entries(testFiles)) {
    const filePath = path.join(testDir, file);
    await mkdir(path.dirname(filePath), { recursive: true });
    await writeFile(filePath, content, "utf8");
  }

  await mkdir(path.join(testDir, "fixtures"), { recursive: true });

  console.log(`Scaffolded app/tools/${slug}/ and tests/tools/${slug}/`);
  console.log("Run `npm run tools:registry` to add it to the homepage, then replace the TODOs.");
}

main();
